import React,{useEffect,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {ArrowRight,ArrowUpRight,BookOpen,Check,CheckCheck,ChevronDown,ChevronRight,Clock3,Database,Download,Earth,ExternalLink,FileText,FolderHeart,History,Info,KeyRound,LoaderCircle,LockKeyhole,Menu,Plus,Search,Settings2,ShieldCheck,SlidersHorizontal,Sparkles,Trash2,X} from 'lucide-react';
import {api,countries,dayOffset,displayDate,Doc,Evidence,initialize,statusNames,topics} from './api';
import {Globe} from './Globe';
import './style.css';

const genre:Record<string,string>={opiniao:'Opinião sinalizada',comunicado_institucional:'Comunicado institucional',entrevista_sinalizada:'Entrevista sinalizada',investigacao_sinalizada:'Investigação sinalizada',apuracao_nao_verificada:'Apuração não verificada',reproducao_agencia:'Reprodução de agência'};
const access:Record<string,string>={texto_extraido:'Texto extraído',pdf_extraido:'PDF extraído',resumo_do_feed:'Trecho do feed',somente_metadados:'Só metadados',parcial_restrito:'Acesso restrito'};
type Page='explorar'|'historico'|'configuracoes';
function IconButton({children,...props}:React.ButtonHTMLAttributes<HTMLButtonElement>){return <button className="icon-button" {...props}>{children}</button>}
function Modal({title,close,children}:{title:string;close:()=>void;children:React.ReactNode}){
 useEffect(()=>{const listener=(event:KeyboardEvent)=>{if(event.key==='Escape')close()};document.addEventListener('keydown',listener);return()=>document.removeEventListener('keydown',listener)},[close]);
 return <div className="modal-backdrop" onClick={e=>{if(e.target===e.currentTarget)close()}}><section className="modal" role="dialog" aria-modal="true" aria-label={title}><header><h2>{title}</h2><IconButton aria-label="Fechar janela" onClick={close}><X size={20}/></IconButton></header>{children}</section></div>
}
function isAIConfigured(settings:any){
 return !!settings?.allow_ai && (settings.provider==='ollama'?!!settings.ollama_model?.trim():settings.provider==='codex'?!!settings.codex_model?.trim():settings.provider==='openai'&&!!settings.key_configured&&!!settings.model?.trim());
}
function App(){
 const [analysisVersion,setAnalysisVersion]=useState('');
 const [elapsed,setElapsed]=useState(0);

 const [analysisProgress,setAnalysisProgress]=useState<any>(null);

 const [ready,setReady]=useState(false),[page,setPage]=useState<Page>('explorar'),[settings,setSettings]=useState<any>(null),[sources,setSources]=useState<any[]>([]);
 const [selected,setSelected]=useState(['BR','US']),[chosenTopics,setChosenTopics]=useState<string[]>([]),[keyword,setKeyword]=useState(''),[start,setStart]=useState(dayOffset(-7)),[end,setEnd]=useState(dayOffset(-1)),[range,setRange]=useState(true);
 const [query,setQuery]=useState<any>(null),[busy,setBusy]=useState(''),[error,setError]=useState(''),[notice,setNotice]=useState(''),[showCoverage,setShowCoverage]=useState(false),[showPlan,setShowPlan]=useState<any>(null),[document,setDocument]=useState<Doc|null>(null),[mobile,setMobile]=useState(false);
 useEffect(()=>{if(!busy)return;const start=Date.now();setElapsed(0);const timer=setInterval(()=>setElapsed(Math.floor((Date.now()-start)/1000)),1000);return()=>clearInterval(timer)},[busy]);
 useEffect(()=>{setAnalysisProgress(null)},[query?.id]);
 useEffect(()=>{if(!['Gerando resumo','Gerando cruzamentos'].includes(busy)||!query?.id)return;let active=true;const timer=setInterval(async()=>{try{const next=await api('/queries/'+query.id+'/analysis-progress');if(active)setAnalysisProgress(next)}catch{}},1200);return()=>{active=false;clearInterval(timer)}},[busy,query?.id]);
 const refreshSettings=async()=>{setSettings(await api('/settings'));setSources(await api('/sources'));};
 useEffect(()=>{initialize().then(async()=>{await refreshSettings();setReady(true)}).catch(e=>setError(e.message))},[]);
 useEffect(()=>{if(!query||query.status!=='coletando')return;const interval=setInterval(async()=>{try{const next=await api('/queries/'+query.id);setQuery(next);if(next.status!=='coletando'){setBusy('');setSources(await api('/sources'));}}catch(e:any){setError(e.message);setBusy('');clearInterval(interval)}},1500);return()=>clearInterval(interval)},[query?.id,query?.status]);
 async function action(label:string,fn:()=>Promise<void>){setError('');setNotice('');setBusy(label);try{await fn()}catch(e:any){setError(e.message)}finally{setBusy('')}}
 function toggle(code:string){setSelected(prev=>prev.includes(code)?prev.filter(c=>c!==code):[...prev,code]);}
 function navigate(next:Page){setPage(next);setMobile(false);setError('');setNotice('')}
 async function search(mode:string){setError('');setNotice('');setQuery(null);setBusy(mode==='collect'?'Consultando as fontes':'Buscando no acervo');try{const result=await api('/queries','POST',{countries:selected,topics:chosenTopics,keyword,start,end:range?end:start,mode});setQuery(result)}catch(e:any){setError(e.message);setBusy('')}}
 async function openQuery(id:string){await action('Abrindo consulta',async()=>{const result=await api('/queries/'+id);setQuery(result);setSelected(result.filters.countries);setChosenTopics(result.filters.topics);setKeyword(result.filters.keyword);setStart(result.filters.start);setEnd(result.filters.end);setRange(result.filters.start!==result.filters.end);setPage('explorar');});}
 const result=query?.result,analysis=query?.analyses?.find((a:any)=>(a.config.analysis_kind||'summary')==='summary');
 const crossingsVersions=(query?.analyses||[]).filter((a:any)=>a.config.analysis_kind==='crossings'&&a.config.summary_id===analysis?.id),crossings=crossingsVersions.find((a:any)=>a.id===analysisVersion)||crossingsVersions[0];
 const configured=isAIConfigured(settings),setupBlocked=ready&&!configured&&page!=='configuracoes';
 return <div className="app-shell"><div inert={setupBlocked} className={setupBlocked?"setup-dimmed":undefined}><aside className={'sidebar '+(mobile?'open':'')}><a className="brand" href="#" onClick={e=>{e.preventDefault();navigate('explorar')}}><span className="brand-symbol"><Earth size={25} strokeWidth={1.4}/></span><span>Observatório</span></a><button className="new-search" onClick={()=>{setQuery(null);navigate('explorar')}}><Plus size={17}/> Nova exploração</button><div className="nav-caption">SEU ESPAÇO DE PESQUISA</div><nav>{([['explorar',Earth,'Explorar'],['historico',History,'Histórico'],['configuracoes',Settings2,'Configurações']] as const).map(([id,Icon,label])=><button key={id} aria-current={page===id?'page':undefined} className={page===id?'active':''} onClick={()=>navigate(id)}><Icon size={18}/>{label}{page===id&&<span className="nav-dot"/>}</button>)}</nav><div className="sidebar-bottom"><div className="local-badge"><span/> Seu acervo, no seu computador</div><p>Conecte perspectivas.<br/>Preserve as evidências.</p><div className="pilot"><span>PILOTO 0.1</span><span>4 países · {sources.length} fontes</span></div></div></aside>
 <div className="main-shell"><header className="topbar"><div className="breadcrumb"><IconButton aria-label="Abrir navegação" onClick={()=>setMobile(!mobile)}><Menu size={20}/></IconButton><span>Observatório</span><ChevronRight size={12}/><strong>{page==='explorar'?'Explorar':page==='historico'?'Histórico':'Configurações'}</strong></div><div className="top-status"><span className="green-dot"/> Ambiente local <span className="top-divider"/> <LockKeyhole size={13}/> Acervo privado</div></header>
 <main>{error&&<div role="alert" className="alert error"><Info size={18}/><span>{error}</span><IconButton aria-label="Dispensar erro" onClick={()=>setError('')}><X size={16}/></IconButton></div>}{notice&&<div role="status" className="alert success"><Check size={18}/><span>{notice}</span></div>}
 {settings?.provider==='codex'&&<CodexLimits refreshKey={busy}/>}
 {!ready?<div className="empty"><LoaderCircle className="spin"/><h2>Preparando seu observatório</h2><p>Conectando ao acervo local.</p></div>:page==='explorar'?<>
 <section className="intro"><div><div className="eyebrow"><span/> PERSPECTIVAS DO MUNDO</div><h1>Explore os fatos.<br/><span>Conecte perspectivas.</span></h1><p>Explore notícias e documentos, compare o que as fontes dizem<br className="desktop-break"/> e construa uma análise com referências que você pode conferir.</p></div><div className="intro-note"><BookOpen size={18}/><p>Primeiro, as fontes.<br/><strong>Depois, as conexões.</strong></p></div></section>
 <section className="world-panel"><Globe selected={selected} toggle={toggle}/><div className="country-panel"><div className="step-title"><span>01</span> Escolha as perspectivas</div><h2>De onde você quer olhar?</h2><p>Selecione um ou mais países. A busca fica restrita às fontes cadastradas de cada um.</p><div className="country-options">{Object.entries(countries).map(([code,name])=><button key={code} className={'country-option '+(selected.includes(code)?'selected':'')} aria-pressed={selected.includes(code)} onClick={()=>toggle(code)}><span className="country-code">{code}</span><span><strong>{name}</strong><small>5 por tema · 10 jornais · 1 governo · 5 universidades</small></span><span className="checkbox">{selected.includes(code)&&<Check size={14}/>}</span></button>)}</div><div className="selection-note"><span className="green-dot"/>{selected.length} {selected.length===1?'país selecionado':'países selecionados'}<span className="note-divider">·</span>Seleção múltipla</div></div></section>
 <section className="search-panel"><div className="step-title"><span>02</span> Defina sua investigação</div><div className="keyword-box"><Search size={20}/><input aria-label="Palavra-chave" placeholder="Qual assunto você quer explorar? Ex.: Samsung, energia, Marte…" value={keyword} onInput={e=>setKeyword(e.currentTarget.value)} onChange={e=>setKeyword(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&selected.length&&!busy)search('archive')}}/><span>PALAVRA-CHAVE</span></div><p className="field-hint">Busca nos títulos e textos lidos, no idioma original. “Samsung” não altera os países selecionados.</p><div className="filter-heading"><span><SlidersHorizontal size={15}/> Temas</span><button className="text-button" onClick={()=>setChosenTopics([])}>Todos os temas</button></div><div className="topic-list">{Object.entries(topics).map(([id,label])=><button key={id} aria-pressed={chosenTopics.includes(id)} className={'topic '+(chosenTopics.includes(id)?'selected':'')} onClick={()=>setChosenTopics(prev=>prev.includes(id)?prev.filter(t=>t!==id):[...prev,id])}>{chosenTopics.includes(id)&&<Check size={12}/>} {label}</button>)}</div><div className="date-actions"><div className="date-area"><label>Data de publicação</label><div className="date-controls"><select aria-label="Tipo de período" value={range?'range':'day'} onChange={e=>setRange(e.target.value==='range')}><option value="range">Intervalo</option><option value="day">Data única</option></select><input aria-label="Data inicial" type="date" value={start} onInput={e=>setStart(e.currentTarget.value)} onChange={e=>setStart(e.target.value)}/>{range&&<><span>até</span><input aria-label="Data final" type="date" min={start} value={end} onInput={e=>setEnd(e.currentTarget.value)} onChange={e=>setEnd(e.target.value)}/></>}<button className="text-button" onClick={()=>{setStart(dayOffset(-1));setEnd(dayOffset(-1));setRange(false)}}>Ontem</button></div></div><div className="search-actions"><button className="button secondary" disabled={!selected.length||!!busy||!start||!end} onClick={()=>search('archive')}><Database size={16}/> Buscar no acervo</button><button className="button primary" disabled={!selected.length||!!busy||!start||!end} onClick={()=>search('collect')}>Buscar nas fontes <ArrowRight size={17}/></button></div></div><div className="search-footer"><Info size={13}/> Novas buscas consultam os canais recentes. Datas antigas dependem do acervo e de arquivos acessíveis.</div></section>
 {busy&&<div role="status" className="progress-card"><LoaderCircle size={21} className="spin"/><div><strong>{busy} · {elapsed}s</strong><p>{query?.progress?`${query.progress.completed} de ${query.progress.total} fontes · ${query.progress.source}`:'O conteúdo disponível será apresentado, mesmo com falhas em outras fontes.'}</p></div>{query?.progress&&<progress value={query.progress.completed} max={query.progress.total}/>}</div>}
 {analysisProgress&&<div className="analysis-meter" role="status"><div><span>{error||analysisProgress.label}</span><strong>{error||analysisProgress.state==='error'?'Interrompida':`${analysisProgress.percent}%`}</strong></div><progress aria-label="Progresso estimado da análise" max="100" value={analysisProgress.percent}/><small>{error||analysisProgress.state==='error'?'A execução terminou com erro; não está mais processando.':analysisProgress.percent===100?'Concluída e salva no acervo.':'Estimativa durante a geração. 100% somente após validar e salvar.'}</small></div>}
 {result?<section className="results"><div className="section-heading"><div><div className="eyebrow">SEU RECORTE DOCUMENTAL</div><h2>{query.filters.keyword?`Explorando “${query.filters.keyword}”`:'O que as fontes publicaram'}</h2><p>{displayDate(query.filters.start)} a {displayDate(query.filters.end)} · {result.documents.length} documentos · {query.filters.mode==='collect'?'Coleta + acervo':'Acervo local'}</p></div><div className="inline-actions"><button className="button secondary" onClick={()=>setShowCoverage(true)}><ShieldCheck size={15}/> Cobertura</button><button className="button primary" disabled={!!query.saved_at||!!busy} onClick={()=>action('Salvando consulta',async()=>{setQuery(await api('/queries/'+query.id+'/save','POST',{}));setNotice('Consulta salva no histórico. Você poderá reabri-la sem gerar a análise novamente.');})}>{query.saved_at?<CheckCheck size={16}/>:<FolderHeart size={16}/>} {query.saved_at?'Salva no histórico':'Salvar no histórico'}</button></div></div>
 {result.routing&&<div className="evidence-banner"><Info size={17}/><p><strong>Fontes da busca: {result.routing.topics.length?result.routing.topics.map((t:string)=>topics[t]).join(' + '):result.routing.mode==='general'?'Jornalismo geral':'Selecione um tema'} · {result.routing.source_count} cadastradas{result.routing.disabled_count?` · ${result.routing.disabled_count} desativadas`:''}.</strong> {result.routing.reason}</p></div>}<div className="evidence-banner"><Info size={17}/><p><strong>{result.coverage.filter((c:any)=>c.matches>0).length} de {result.coverage.length} fontes com resultados neste recorte.</strong> {result.undated_excluded>0?`${result.undated_excluded} itens sem data verificável ficaram fora dos filtros. `:''}A análise considera somente os textos disponíveis. <button className="text-button" onClick={()=>setShowCoverage(true)}>Ver lacunas</button></p></div>
 {!result.documents.length?<div className="empty compact"><Search size={28}/><h3>Nenhum documento neste recorte do acervo</h3><p>Experimente ampliar as datas, remover um tema ou buscar novas informações nas fontes.<br/>Isso não significa que a notícia não exista. Arquivos antigos podem estar inacessíveis.</p></div>:<><div className="analysis-action"><div><span className="small-icon"><Sparkles size={19}/></span><div><h3>{analysis?'Síntese por país disponível':'Resumo com referências'}</h3><p>{analysis?`Versão ${analysis.version} · ${analysis.config.model} · referências preservadas`:'Síntese por país a partir dos trechos relevantes, com referências.'}</p></div></div><button className="button secondary" disabled={!!busy} onClick={()=>action('Preparando análise',async()=>setShowPlan(await api('/queries/'+query.id+'/analysis-plan?kind=summary')))}><Sparkles size={15}/>{analysis?'Novo resumo':'Preparar resumo'}<ArrowUpRight size={15}/></button></div>
 {analysis?.config.evidence_review?.discarded>0&&<p className="alert">Resumo parcial: itens com referências inválidas foram descartados.</p>}{analysis?.result.gaps.length>0&&<details><summary>Limites do resumo</summary><ul>{analysis.result.gaps.map((g:string,i:number)=><li key={i}>{g}</li>)}</ul></details>}<div className="country-results">{query.filters.countries.map((code:string)=>{const docs:Doc[]=result.documents.filter((d:Doc)=>d.country===code);const summaries=analysis?.result.summaries.filter((s:any)=>s.country===code)||[];return <section className="country-result" key={code}><div className="country-result-header"><span className="country-code">{code}</span><h3>{countries[code]}</h3><span>{docs.length} documentos</span></div>{summaries.length?summaries.map((s:any,i:number)=><div key={i} className="summary"><p>{s.text}</p><Citations evidence={s.evidence} documents={result.documents} open={setDocument}/></div>):<p className="result-note">{docs.length?`Evidências no idioma original. Resumo em ${code==='BR'?'português':'inglês'} ainda não gerado.`:'Sem documentos elegíveis nesta consulta; país excluído da análise por falta de evidência.'}</p>}<div className="document-list">{docs.slice(0,4).map(d=><DocumentCard key={d.revision_id} document={d} open={setDocument}/>)}</div>{docs.length>4&&<details><summary>Ver mais {docs.length-4} documentos</summary>{docs.slice(4).map(d=><DocumentCard key={d.revision_id} document={d} open={setDocument}/>)}</details>}</section>})}</div>
 <section className="connections">{busy==='Gerando cruzamentos'&&<div className="progress-card" role="status"><LoaderCircle size={20} className="spin"/><div><strong>Gerando cruzamentos · {Math.floor(elapsed/60)}min {String(elapsed%60).padStart(2,'0')}s</strong><p>{analysisProgress?.label||'Preparando os documentos'}</p></div></div>}<div className="section-heading"><div><div className="eyebrow">ENTRE AS PERSPECTIVAS</div><h2>Cruzamentos e atribuições</h2></div><span className="pill">{result.related_pairs.length} pares candidatos</span></div><button className="button secondary" disabled={!!busy||!analysis||!result.related_pairs.length} onClick={()=>{if(!settings.allow_ai||(settings.provider==='openai'&&!settings.key_configured)){navigate('configuracoes');setNotice('Habilite as análises em Configurações.')}else action('Preparando cruzamentos',async()=>setShowPlan(await api('/queries/'+query.id+'/analysis-plan?kind=crossings')))}}><Sparkles size={15}/>{crossings?'Novos cruzamentos':'Preparar cruzamentos'}</button>{crossings?<AnalysisView analysis={crossings} setVersion={setAnalysisVersion} query={{...query,analyses:crossingsVersions}} documents={result.documents} open={setDocument}/>:<div className="connections-empty"><span className="small-icon"><BookOpen size={22}/></span><h3>Cruzamentos e interpretações sob demanda</h3><p>{!analysis?'Gere primeiro o resumo com referências acima.':result.related_pairs.length?'Resumo pronto. Solicite os cruzamentos quando quiser comparar as fontes.':'Não há pares elegíveis para comparação neste recorte.'}</p></div>}{result.origin_groups.length>0&&<details className="origin-note"><summary>{result.origin_groups.length} grupos com possível origem comum</summary><p>Créditos de agência e semelhança de texto/título são sinais preliminares. Não são confirmações independentes.</p>{result.origin_groups.map((g:any,i:number)=><p key={i}>{g.revision_ids.map((id:number)=>result.documents.find((d:Doc)=>d.revision_id===id)?.source_name).join(' · ')}</p>)}</details>}</section></>}
 <details className="method-note"><summary>Como interpretar esta consulta</summary><ul>{result.limitations.map((l:string)=><li key={l}>{l}</li>)}</ul>{result.truncated&&<p>Exibindo 200 de {result.total_matches} resultados. Reduza o recorte para ler os demais.</p>}<a className="button secondary" href={'/api/queries/'+query.id+'/export'}><Download size={15}/> Exportar consulta e referências</a></details></section>:!busy&&<div className="below-search"><div><Database size={19}/><span><strong>Acervo que permanece</strong><small>Documentos e revisões salvos localmente.</small></span></div><div><BookOpen size={19}/><span><strong>Referências verificáveis</strong><small>Volte ao trecho e à fonte original.</small></span></div><div><Sparkles size={19}/><span><strong>Cruzamentos sob demanda</strong><small>Compare as fontes depois do resumo.</small></span></div></div>}
 </>:page==='historico'?<HistoryPage open={openQuery} action={action}/>:<SettingsPage configured={configured} explore={()=>navigate('explorar')} value={settings} sources={sources} refresh={refreshSettings} action={action} notice={setNotice}/>}
 <footer className="page-footer"><Earth size={14}/><span>Observatório</span><span>Exploração documental. Evidência, contexto e perguntas melhores.</span></footer></main></div></div>
 {setupBlocked&&<div className="setup-backdrop"><section className="setup-dialog" role="dialog" aria-modal="true" aria-labelledby="setup-title" aria-describedby="setup-description"><span className="small-icon"><Settings2 size={24}/></span><div className="eyebrow">ETAPA 1 DE 3 · CONFIGURAÇÃO</div><h2 id="setup-title">Prepare seu Observatório</h2><p id="setup-description">Escolha a IA, configure a conexão e habilite as análises em Configurações. Ao salvar, a exploração será liberada.</p><ol className="setup-steps"><li><strong>Configure a IA</strong><span>Escolha o provedor e o modelo.</span></li><li><strong>Explore as fontes</strong><span>Defina países, assunto e período.</span></li><li><strong>Gere seu resumo</strong><span>Depois, solicite cruzamentos se quiser.</span></li></ol><button autoFocus className="button primary" onClick={()=>navigate('configuracoes')}>Ir para Configurações <ArrowRight size={16}/></button></section></div>}
 {showCoverage&&result&&<Modal title="Cobertura desta consulta" close={()=>setShowCoverage(false)}><p className="muted">Disponibilidade do canal e presença de documentos no recorte são coisas diferentes. Fontes sem resultados ficam fora da análise.</p><div className="coverage-list">{result.coverage.map((c:any)=><div key={c.source_id}><div><strong>{c.name}</strong><span className={'status '+c.status}>{statusNames[c.status]||c.status}</span></div><p>{c.matches} documentos no recorte · {c.checked_at?`Última verificação: ${displayDate(c.checked_at)}`:'Sem teste de rede nesta consulta'}</p><small>{c.detail?.message}</small>{c.detail?.failures?.length>0&&<details><summary>{c.detail.failures.length} falhas de conteúdo</summary>{c.detail.failures.map((f:any,i:number)=><p key={i}><a href={f.url} target="_blank" rel="noreferrer">Abrir fonte</a> · {f.reason}</p>)}</details>}</div>)}</div></Modal>}
 {showPlan&&<Modal title={showPlan.analysis_kind==='crossings'?'Preparar cruzamentos e interpretações':'Preparar resumo com referências'} close={()=>setShowPlan(null)}><div className="plan-grid"><div><strong>{showPlan.document_count}</strong><span>documentos selecionados</span></div><div><strong>{showPlan.input_characters.toLocaleString('pt-BR')}</strong><span>caracteres na entrada</span></div><div><strong>{showPlan.max_output_tokens.toLocaleString('pt-BR')}</strong><span>{showPlan.provider==='codex'?'configuração API/Ollama · não limita Codex':'limite de tokens de saída'}</span></div></div><p><strong>Modelo:</strong> {showPlan.model}</p>{showPlan.provider==='ollama'&&<p className="muted">O limite mostrado reserva espaço para os documentos dentro do contexto local. Tokens são unidades de texto, sem cobrança neste modo. Respostas longas podem levar vários minutos.</p>}<p>{showPlan.notice}</p><p className="muted">{showPlan.excluded_count} documentos ficam fora pelo limite configurado. {showPlan.analysis_kind==='crossings'?`São priorizados pares completos: ${showPlan.pair_count??0} pares elegíveis.`:'São priorizados documentos recentes, alternando os países. Esta etapa gera somente resumos e referências.'} {analysis?'A versão anterior será preservada.':'A análise será reutilizável após ser gerada.'}</p><button className="button primary full" disabled={!!busy||!showPlan.document_count} onClick={()=>action(showPlan.analysis_kind==='crossings'?'Gerando cruzamentos':'Gerando resumo',async()=>{setAnalysisProgress({percent:0,label:'Preparando os documentos',state:'running'});setShowPlan(null);await api('/queries/'+query.id+'/analyze','POST',{kind:showPlan.analysis_kind,regenerate:showPlan.analysis_kind==='crossings'?!!crossings:!!analysis});setAnalysisProgress({percent:100,label:'Análise salva',state:'complete'});setAnalysisVersion('');setQuery(await api('/queries/'+query.id));await refreshSettings()})}><Sparkles size={17}/> {showPlan.analysis_kind==='crossings'?'Gerar cruzamentos':'Gerar resumo'}</button></Modal>}
 {document&&<DocumentModal document={document} close={()=>setDocument(null)}/>}
 </div>
}

function DocumentCard({document:d,open}:{document:Doc;open:(d:Doc)=>void}){return <article className="document-card"><div className="document-meta"><span>{d.source_name}</span><span>{displayDate(d.published_at,true)}</span></div><button className="document-title" onClick={()=>open(d)}>{d.title}<ArrowUpRight size={15}/></button><p>{d.text?d.text.slice(0,185)+(d.text.length>185?'…':''):'Apenas metadados disponíveis. Nenhum conteúdo foi inferido.'}</p><div className="document-tags"><span>{access[d.access]||d.access}</span><span>{genre[d.genre]||'Tipo não verificado'}</span></div></article>}
function Citations({evidence,documents,open}:{evidence:Evidence[];documents:Doc[];open:(d:Doc)=>void}){return <div className="citations">{evidence.map((e,i)=>{const d=documents.find(d=>d.revision_id===e.revision_id);return d?<button key={i} title={e.quote} onClick={()=>open(d)}><FileText size={12}/>{d.source_name} · ref. {e.revision_id}</button>:null})}</div>}
function DocumentModal({document:d,close}:{document:Doc;close:()=>void}){
 const [version,setVersion]=useState<any>(d),[versions,setVersions]=useState<any[]>([]),[error,setError]=useState('');
 useEffect(()=>{api('/revisions/'+d.revision_id).then(v=>setVersions(v.versions)).catch(e=>setError(e.message))},[d.revision_id]);
 return <Modal title="Documento e evidência original" close={close}><div className="document-meta"><span>{d.source_name} · {countries[d.country]}</span><span>Referência {version.revision_id||version.id}</span></div><h2 className="doc-heading">{version.title}</h2><p className="muted">{d.affiliation}</p><div className="document-tags"><span>Publicação: {displayDate(version.published_at,true)}</span><span>Coleta: {displayDate(version.collected_at||version.created_at)}</span><span>{access[version.access]}</span><span>{genre[version.genre]}</span></div><p className="muted">{version.access_note}</p>{version.author&&<p><strong>Autoria/crédito:</strong> {version.author}</p>}{error&&<p role="alert">{error}</p>}{versions.length>1&&<label className="form-field">Revisões preservadas<select value={version.revision_id||version.id} onChange={e=>api('/revisions/'+e.target.value).then(setVersion).catch(e=>setError(e.message))}>{versions.map(v=><option key={v.id} value={v.id}>Revisão {v.id} · coletada em {displayDate(v.created_at)}</option>)}</select></label>}<a className="button secondary" href={d.url} target="_blank" rel="noreferrer"><ExternalLink size={15}/> Abrir publicação original</a><h3>Texto efetivamente lido</h3><div className="original-text">{version.text||'Nenhum texto disponível. Somente metadados foram recuperados.'}</div>{version.study_links?.length>0&&<><h3>Estudos e dados citados pela publicação</h3><p className="muted">Links identificados no documento. O estudo vinculado não foi automaticamente lido nem sua revisão por pares confirmada.</p>{version.study_links.map((l:any)=><p key={l.url}><a href={l.url} target="_blank" rel="noreferrer">{l.label||l.url}</a> · {l.status==='preprint'?'Preprint':'Revisão não verificada'}</p>)}</>}</Modal>
}
function AnalysisView({analysis,setVersion,query,documents,open}:any){
 const a=analysis;
 const result=a.result;
 return <>{a.config.evidence_review?.discarded>0&&<div className="alert" role="status"><Info size={18}/><span>Análise parcial: {a.config.evidence_review.discarded} itens foram descartados por referências ou atribuições inválidas. Os itens exibidos passaram na verificação de referências; confira a interpretação nas fontes.</span></div>}<div className="analysis-version"><label>Versão da análise <select value={a.id} onChange={e=>setVersion(e.target.value)}>{query.analyses.map((v:any)=><option key={v.id} value={v.id}>Versão {v.version} · {displayDate(v.created_at)} · {v.config.model}</option>)}</select></label><span>Brasil em português · demais fontes em inglês · citações originais</span></div>
 {result.comparisons.length?result.comparisons.map((c:any,i:number)=><article className="comparison" key={i}><span className="pill">{({convergencia:'Convergência',divergencia:'Divergência',hipotese:'Hipótese',mudanca_historica:'Mudança histórica'} as any)[c.relation]}</span><h3>{c.title}</h3><p><strong>Observação documental:</strong> {c.observation}</p><p><strong>Inferência:</strong> {c.inference}</p><p><strong>Alternativas:</strong> {c.alternatives}</p><p><strong>Evidência contrária:</strong> {c.counterevidence}</p><p className="muted">{c.caveats}</p><Citations evidence={c.evidence} documents={documents} open={open}/></article>):<p className="result-note">A análise não estabeleceu cruzamentos documentais suficientes neste recorte.</p>}
 <h3 className="subheading">O que disseram sobre outros países</h3>{result.cross_statements.length?result.cross_statements.map((s:any,i:number)=><article className="cross-statement" key={i}><span className="pill">{countries[s.source_country]} → {countries[s.target_country]}</span><p><strong>{s.speaker}:</strong> {s.statement}</p><Citations evidence={s.evidence} documents={documents} open={open}/></article>):<p className="result-note">Nenhuma declaração especificamente atribuída sobre outro país foi identificada nos textos analisados.</p>}
 <details className="claims"><summary>Lacunas e limites desta análise</summary><ul>{result.gaps.map((g:string,i:number)=><li key={i}>{g}</li>)}</ul></details>
 </>
}

function HistoryPage({open,action}:any){
 const [items,setItems]=useState<any[]>([]),[search,setSearch]=useState(''),[country,setCountry]=useState(''),[topic,setTopic]=useState(''),[start,setStart]=useState(''),[end,setEnd]=useState(''),[error,setError]=useState('');
 async function load(){setItems(await api('/history?'+new URLSearchParams({search,country,topic,start,end})))}
 useEffect(()=>{load().catch(e=>setError(e.message))},[search,country,topic,start,end]);
 return <section className="inner-page"><div className="eyebrow">SEU ACERVO DE EXPLORAÇÕES</div><h1>Volte às suas perguntas.</h1><p className="page-description">Consultas que você escolheu salvar, com filtros, evidências e análises preservadas.<br/>Reabrir não faz uma nova coleta nem uma nova chamada à IA.</p><div className="history-filters"><div className="input-icon"><Search size={17}/><input aria-label="Buscar no histórico" placeholder="Buscar consulta salva…" value={search} onInput={e=>setSearch(e.currentTarget.value)} onChange={e=>setSearch(e.target.value)}/></div><select aria-label="Filtrar país no histórico" value={country} onChange={e=>setCountry(e.target.value)}><option value="">Todos os países</option>{Object.entries(countries).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select><select aria-label="Filtrar tema no histórico" value={topic} onChange={e=>setTopic(e.target.value)}><option value="">Todos os temas</option>{Object.entries(topics).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select><label>Publicações de<input type="date" aria-label="Início do filtro de histórico" value={start} onInput={e=>setStart(e.currentTarget.value)} onChange={e=>setStart(e.target.value)}/></label><label>até<input type="date" aria-label="Fim do filtro de histórico" value={end} onInput={e=>setEnd(e.currentTarget.value)} onChange={e=>setEnd(e.target.value)}/></label></div>{error&&<p role="alert">{error}</p>}{items.length?<div className="history-list">{items.map(item=><article key={item.id}><span className="history-icon"><BookOpen size={22}/></span><button className="history-open" onClick={()=>open(item.id)}><h3>{item.title}</h3><p>{displayDate(item.filters.start)} a {displayDate(item.filters.end)} · {item.filters.countries.map((c:string)=>countries[c]).join(', ')}</p><small>Salva em {displayDate(item.saved_at)} · {(item.filters.topics.length?item.filters.topics.map((t:string)=>topics[t]):['Todos os temas']).join(' · ')}</small></button><a className="icon-button" title="Exportar consulta" aria-label="Exportar consulta" href={'/api/queries/'+item.id+'/export'}><Download size={17}/></a><IconButton aria-label="Remover do histórico" title="Remover somente da lista de histórico" onClick={()=>action('Atualizando histórico',async()=>{await api('/history/'+item.id,'DELETE');await load()})}><Trash2 size={17}/></IconButton><ChevronRight size={17}/></article>)}</div>:<div className="empty"><FolderHeart size={36}/><h2>Suas explorações ficam aqui</h2><p>Depois de uma consulta, use “Salvar no histórico”.<br/>Se já salvou, tente limpar os filtros acima.</p></div>}</section>
}

function CodexLimits({refreshKey}:{refreshKey:string}){
 const [limits,setLimits]=useState<any>(null);
 useEffect(()=>{let active=true,pending=false;const update=async()=>{if(pending)return;pending=true;try{const r=await api('/codex/limits');if(active)setLimits(r)}catch{if(active)setLimits({unavailable:true,message:'Limites indisponíveis no momento.'})}finally{pending=false}};update();const timer=setInterval(update,60000);return()=>{active=false;clearInterval(timer)}},[refreshKey]);
 const buckets:any[]=limits?.rateLimitsByLimitId?Object.values(limits.rateLimitsByLimitId):limits?.rateLimits?[limits.rateLimits]:[];
 return <details className="settings-card" open><summary>Uso do Codex · conta ChatGPT</summary>{!limits?<p>Consultando limites…</p>:<><p className="muted">Cota compartilhada com outros usos da conta. Atualiza a cada minuto e após a geração.</p>{limits.message&&<p>{limits.message}</p>}{buckets.map((b:any,i:number)=><div key={b.limitId||i}>{['primary','secondary'].map(k=>{const w=b[k];if(w?.usedPercent==null)return null;const used=Math.max(0,Math.min(100,w.usedPercent));return <div className="analysis-meter" key={k}><div><span>{b.limitName||b.limitId||'Codex'} · {w.windowDurationMins?`${w.windowDurationMins/60}h`:'janela não informada'}</span><strong>{used}% usado · {Math.round(100-used)}% disponível</strong></div><progress max="100" value={used}/>{used>=90&&<p role="alert">Atenção: restam {Math.round(100-used)}% nesta janela.</p>}<small>{w.resetsAt?'Renova em '+new Date(w.resetsAt*1000).toLocaleString('pt-BR'):'Renovação não informada'}</small></div>})}</div>)}{!buckets.length&&<p className="muted">Percentuais ainda não informados.</p>}{limits.observatorio_tokens!=null&&<p>Tokens registrados pelo Observatório: <strong>{limits.observatorio_tokens.toLocaleString('pt-BR')}</strong>{limits.token_records_incomplete?' (parcial; algumas gerações não informaram tokens)':''}. Não representa o total usado em outros aplicativos.</p>}</>}</details>
}
function SettingsPage({value,sources,refresh,action,notice,configured,explore}:any){
 const [hardware,setHardware]=useState<any>(null),[codex,setCodex]=useState<any>(null),[authUrl,setAuthUrl]=useState('');
 const [form,setForm]=useState<any>(value),[key,setKey]=useState(''),[sourceSearch,setSourceSearch]=useState(''),[sourceCountry,setSourceCountry]=useState(''),[sourceKind,setSourceKind]=useState(''),[sourceTopic,setSourceTopic]=useState(''),[sourceGroup,setSourceGroup]=useState(''),[expanded,setExpanded]=useState(''),[importSource,setImportSource]=useState('agbr'),[importUrl,setImportUrl]=useState(''),[backup,setBackup]=useState('');
 useEffect(()=>setForm(value),[value]);
 async function save(){await api('/settings','PUT',form);await refresh();notice('Configurações salvas no computador.')}
 const filtered=sources.filter((s:any)=>(!sourceCountry||s.country===sourceCountry)&&(!sourceKind||s.kind===sourceKind)&&(!sourceTopic||(s.topics||[]).includes(sourceTopic))&&(!sourceGroup||(s.groups||[]).includes(sourceGroup))&&(s.name+' '+s.affiliation).toLowerCase().includes(sourceSearch.toLowerCase()));
 return <section className="inner-page settings-page"><div className="eyebrow">DO SEU JEITO</div><h1>Seu observatório, suas escolhas.</h1><p className="page-description">Configure a análise, conheça as fontes e cuide do seu acervo local.</p>
 <section className="settings-card setup-guide"><div className="eyebrow">ETAPA 1 · CONFIGURAÇÃO</div><h2>{configured?'Configuração salva. Pronto para explorar.':'Configure a IA para começar'}</h2><p>Escolha o provedor e o modelo, configure a conexão, marque “Habilitar análises” e salve. O perfil do computador é opcional e se aplica ao Ollama.</p>{configured?<button className="button primary" onClick={explore}>Explorar fontes <ArrowRight size={16}/></button>:<p className="muted">A exploração será liberada após salvar os dados necessários. Nenhum resumo será gerado automaticamente.</p>}</section><section className="settings-card"><h2>Recursos deste computador</h2><p>Perfil automático usa os dispositivos detectados nesta máquina. A GPU pode compartilhar a memória do Windows.</p><button className="button secondary" onClick={()=>action('Verificando computador',async()=>setHardware(await api('/hardware')))}>Verificar este computador</button>{hardware&&<div className="settings-info"><p><strong>{hardware.cpu}</strong> · {hardware.threads??'?'} processadores lógicos</p><p>RAM: {hardware.memory_total_gb??'não verificada'} GB · disponível: {hardware.memory_available_gb??'não verificada'} GB</p><p>GPU: {hardware.gpus.join(', ')||'não verificada'} · Ollama: {hardware.ollama_version||'não conectado'}</p>{hardware.loaded_models.map((m:any)=><p key={m.name}>{m.name}: {m.size_vram>0?'uso de memória de GPU reportado':'sem uso de GPU reportado'}</p>)}{hardware.notes.map((n:string,i:number)=><p key={i}>{n}</p>)}<button className="button secondary" onClick={()=>setForm({...form,resource_profile:hardware.recommendation,memory_reserve_gb:hardware.reserve_gb})}>Usar recomendação</button></div>}<div className="settings-grid"><label className="form-field">Perfil<select value={form.resource_profile||'auto'} onChange={e=>setForm({...form,resource_profile:e.target.value})}><option value="auto">Automático · CPU e GPU compatível</option><option value="cpu">Somente CPU</option></select></label><label className="form-field">Margem de memória livre (GB)<input type="number" min="1" max="32" value={form.memory_reserve_gb??3} onChange={e=>setForm({...form,memory_reserve_gb:Number(e.target.value)})}/></label></div><p className="muted">Uma geração por vez. A margem impede iniciar com pouca RAM; não é um teto rígido durante a execução. Aplicar reinicia apenas o Ollama desta instalação, se estiver livre.</p><button className="button primary" onClick={()=>action('Aplicando perfil',async()=>{await save();const r=await api('/hardware/apply','POST',{});notice(r.message);setHardware(await api('/hardware'))})}>Salvar e aplicar perfil</button></section><section className="settings-card"><h2>Como gerar suas análises</h2><label className="form-field">Provedor de análise<select aria-label="Provedor de análise" value={form.provider||'openai'} onChange={e=>setForm({...form,provider:e.target.value,...(e.target.value==='ollama'?{max_documents:4,max_chars_per_document:1000,max_output_tokens:32768,ollama_context:32768}:{})})}><option value="ollama">Ollama local · sem chave OpenAI</option><option value="openai">OpenAI · API paga</option><option value="codex">Codex · entrar com ChatGPT (teste)</option></select></label>{form.provider==='codex'&&<div className="settings-info"><p>Login ChatGPT separado para o Observatório. Consome sua cota do Codex, compartilhada com outros usos; não exige chave API.</p><div className="inline-actions"><button className="button secondary" onClick={()=>action('Conectando ChatGPT',async()=>{const r=await api('/codex/login','POST',{});setAuthUrl(r.auth_url||'');notice(r.message)})}>Entrar com ChatGPT</button><button className="button secondary" onClick={()=>action('Verificando conexão Codex',async()=>{const r=await api('/codex/status');setCodex(r);notice(r.message)})}>Verificar conexão e modelos</button></div>{authUrl&&<p><a className="button primary" href={authUrl} target="_blank" rel="noreferrer">Concluir login no navegador</a></p>}{codex&&<p>{codex.connected?'ChatGPT conectado · '+(codex.plan||'plano não informado'):codex.message}</p>}<label className="form-field">Modelo GPT no Codex<select aria-label="Modelo GPT no Codex" value={form.codex_model||''} onChange={e=>setForm({...form,codex_model:e.target.value})}><option value="">Verifique a conexão e escolha um modelo</option>{form.codex_model&&!codex?.models?.some((m:any)=>m.id===form.codex_model)&&<option value={form.codex_model}>{form.codex_model}</option>}{(codex?.models||[]).map((m:any)=><option key={m.id} value={m.id}>{m.name}</option>)}</select></label><p>Depois de entrar, verifique a conexão, escolha o modelo, habilite as análises e salve. O contador de tokens abaixo é referente à API/Ollama; no Codex, acompanhe a cota da assinatura.</p></div>}{form.provider==='ollama'&&<><p className="settings-info">Os textos serão analisados pelo modelo instalado no computador. A geração local não usa créditos OpenAI. Comece com poucos documentos.</p><div className="settings-grid"><label className="form-field">Modelo local<input aria-label="Modelo Ollama" value={form.ollama_model||'qwen3.5:4b'} onChange={e=>setForm({...form,ollama_model:e.target.value})}/></label><label className="form-field">Contexto local (tokens)<input type="number" min="8192" max="65536" value={form.ollama_context||16384} onChange={e=>setForm({...form,ollama_context:Number(e.target.value)})}/></label></div><button className="button secondary" onClick={()=>action('Conferindo Ollama',async()=>{const r=await api('/ollama/status');notice(r.reachable?`Ollama conectado. Modelos locais: ${r.models.join(', ')||'nenhum'}. Salve as configurações após escolher o modelo.`:r.message)})}>Verificar Ollama e modelos</button><p className="field-hint">Para instalar o Qwen ou iniciar o serviço, use Instalar-Qwen.cmd na pasta do aplicativo.</p></>}</section>
 <section className="settings-card">{form.provider==='openai'&&<><div className="card-heading"><span className="small-icon"><KeyRound size={21}/></span><div><h2>Conexão com a OpenAI</h2><p>Uma chave pessoal para gerar resumos e cruzamentos.</p></div><span className={'pill '+(value.key_configured?'green':'')}>{value.key_configured?'Chave configurada':'Sem chave'}</span></div><p className="settings-info">A API é paga separadamente da assinatura do ChatGPT. Seu acervo fica neste computador; ao gerar um resumo ou cruzamento, os textos selecionados são enviados pela internet à OpenAI.</p><label className="form-field">Chave da API<div className="key-row"><input autoComplete="off" type="password" aria-label="Chave da API OpenAI" value={key} placeholder={value.key_configured?'Uma chave está guardada no cofre do sistema':'Cole sua chave pessoal da OpenAI'} onInput={e=>setKey(e.currentTarget.value)} onChange={e=>setKey(e.target.value)}/><button className="button secondary" disabled={key.length<16} onClick={()=>action('Guardando chave',async()=>{await api('/key','PUT',{key});setKey('');await refresh();notice('Chave guardada no cofre de credenciais do sistema.');})}>Guardar chave</button></div></label><div className="key-actions"><small><LockKeyhole size={12}/> A chave não é incluída no aplicativo compilado, nos logs ou no backup.</small><button className="text-button" disabled={!value.key_configured} onClick={()=>action('Testando acesso',async()=>notice((await api('/key/test','POST',{})).message))}>Testar acesso ao modelo</button><button className="text-button danger" disabled={!value.key_configured} onClick={()=>action('Removendo chave',async()=>{await api('/key','DELETE');await refresh();notice('Credencial removida do cofre. Se houver chave no ambiente, remova-a e reinicie.');})}>Remover chave</button></div>
 </>}<div className="settings-grid">{form.provider==='openai'&&<label className="form-field">Modelo para análise<input value={form.model} onChange={e=>setForm({...form,model:e.target.value})}/><small>Informe um modelo da sua conta compatível com Responses e saídas estruturadas.</small></label>}<label className="form-field">Máximo de documentos por análise<input type="number" min="1" max="40" value={form.max_documents} onChange={e=>setForm({...form,max_documents:Number(e.target.value)})}/></label><label className="form-field">Caracteres por documento<input type="number" min="1000" max="16000" step="1000" value={form.max_chars_per_document} onChange={e=>setForm({...form,max_chars_per_document:Number(e.target.value)})}/></label><label className="form-field">Limite de tokens da resposta<input type="number" min="1000" max="32768" step="1000" value={form.max_output_tokens} onChange={e=>setForm({...form,max_output_tokens:Number(e.target.value)})}/></label></div><label className="consent"><input type="checkbox" checked={form.allow_ai} onChange={e=>setForm({...form,allow_ai:e.target.checked})}/><span><strong>{form.provider==='ollama'?'Habilitar análises locais':form.provider==='codex'?'Habilitar análises com minha conta ChatGPT':'Habilitar análises com minha API'}</strong><small>{form.provider==='ollama'?'A geração acontece somente quando você solicitar. Nenhum texto é enviado à OpenAI.':form.provider==='codex'?'Envia os trechos selecionados à OpenAI e consome os limites do Codex da sua conta.':'As chamadas acontecem somente ao acionar a geração. Limites de tamanho não garantem um teto de gasto.'}</small></span></label><button className="button primary" onClick={()=>action('Salvando configurações',save)}>Salvar configurações <Check size={16}/></button>
 {value.usage.length>0&&<details className="usage"><summary>Consumo registrado nas últimas 50 chamadas</summary><p className="muted">Uso registrado por modelo. Gerações Ollama são locais; apenas chamadas OpenAI têm faturamento de API.</p><div className="table-scroll"><table><thead><tr><th>Operação</th><th>Modelo</th><th>Data</th><th>Entrada</th><th>Saída</th></tr></thead><tbody>{value.usage.filter((u:any)=>u.operation==='analysis').map((u:any)=><tr key={u.id}><td>Análise</td><td>{u.model}</td><td>{displayDate(u.created_at)}</td><td>{u.usage.input_tokens??`${u.usage.input_characters} caracteres`}</td><td>{u.usage.output_tokens??'Não informada'}</td></tr>)}</tbody></table></div></details>}</section>
 <section className="settings-card"><div className="card-heading"><span className="small-icon"><Database size={21}/></span><div><h2>Acervo e backup</h2><p>Documentos, revisões e análises que permanecem seus.</p></div></div><div className="stat-row">{[['documents','documentos'],['revisions','revisões'],['analyses','análises']].map(([id,label])=><div key={id}><strong>{value.counts[id]}</strong><span>{label}</span></div>)}</div><p className="muted">Pasta de dados: <code>{value.data_dir}</code></p><div className="inline-actions"><button className="button secondary" onClick={()=>action('Preparando backup',async()=>{const b=await api('/backup','POST',{});setBackup(b.id);notice(b.message)})}><Download size={16}/> Criar backup completo</button>{backup&&<a className="button primary" href={'/api/backups/'+backup}>Baixar backup <Download size={16}/></a>}</div><p className="field-hint">Restauração para uma pasta nova, sem substituir seu acervo: siga as instruções de restauração no README do aplicativo.</p><details><summary>Adicionar publicação por URL de uma fonte cadastrada</summary><p className="muted">Útil para uma publicação antiga que você já encontrou ou um PDF aberto. O domínio deve pertencer à fonte; acesso restrito não é contornado. Sem data verificável, o documento fica fora das consultas por período.</p><div className="import-row"><select aria-label="Fonte da publicação a importar" value={importSource} onChange={e=>setImportSource(e.target.value)}>{sources.map((s:any)=><option value={s.id} key={s.id}>{s.name}</option>)}</select><input aria-label="URL da publicação" type="url" placeholder="https://…" value={importUrl} onInput={e=>setImportUrl(e.currentTarget.value)} onChange={e=>setImportUrl(e.target.value)}/><button className="button secondary" disabled={!importUrl} onClick={()=>action('Lendo publicação',async()=>{const r=await api('/import','POST',{source_id:importSource,url:importUrl});await refresh();notice(r.notice);setImportUrl('')})}>Ler e guardar</button></div></details></section>
 <section className="settings-card source-catalog"><div className="card-heading"><span className="small-icon"><BookOpen size={21}/></span><div><h2>Fontes e cobertura</h2><p>Por país: 5 fontes por tema, 10 veículos, 1 governo e 5 universidades.</p></div><span className="pill">{sources.length} fontes únicas</span></div><p className="settings-info">Seleção por diversidade de formatos e vínculos, alcance nacional e disponibilidade de canais públicos. China inclui Hong Kong; Rússia inclui veículos de origem russa no exílio. Universidades selecionadas por destaque acadêmico e produção científica; não é um ranking absoluto. Afiliação editorial não é uma nota de verdade.</p><div className="source-filters"><div className="input-icon"><Search size={16}/><input aria-label="Buscar fonte" placeholder="Buscar fonte ou vínculo…" value={sourceSearch} onInput={e=>setSourceSearch(e.currentTarget.value)} onChange={e=>setSourceSearch(e.target.value)}/></div><select aria-label="País do catálogo" value={sourceCountry} onChange={e=>setSourceCountry(e.target.value)}><option value="">Todos os países</option>{Object.entries(countries).map(([k,v])=><option value={k} key={k}>{v}</option>)}</select><select aria-label="Tema das fontes" value={sourceTopic} onChange={e=>setSourceTopic(e.target.value)}><option value="">Todos os temas</option>{Object.entries(topics).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select><select aria-label="Grupo de fontes" value={sourceGroup} onChange={e=>setSourceGroup(e.target.value)}><option value="">Todos os grupos</option><option value="jornalismo_geral">10 veículos por país</option><option value="governo">Governo principal</option><option value="universidades">5 universidades por país</option></select><select aria-label="Tipo de fonte" value={sourceKind} onChange={e=>setSourceKind(e.target.value)}><option value="">Todos os tipos</option><option value="jornalismo">Jornalismo</option><option value="universidade">Universidades</option><option value="instituicao">Instituições</option></select></div><p className="muted">{filtered.length} fontes neste filtro. Uma fonte pode participar de vários temas e é consultada uma única vez por busca.</p><div className="source-list">{filtered.map((s:any)=><div key={s.id} className="source-item"><div className="source-row"><label className="source-enable"><input type="checkbox" aria-label={'Incluir '+s.name} checked={!form.disabled_sources.includes(s.id)} onChange={e=>setForm({...form,disabled_sources:e.target.checked?form.disabled_sources.filter((id:string)=>id!==s.id):[...form.disabled_sources,s.id]})}/></label><span className="country-code small">{s.country}</span><button className="source-expand" aria-expanded={expanded===s.id} onClick={()=>setExpanded(expanded===s.id?'':s.id)}><strong>{s.name}</strong><small>{s.kind==='jornalismo'?'Jornalismo':s.kind==='universidade'?'Universidade':'Instituição pública/científica'}</small></button><span className={'status '+s.status}>{statusNames[s.status]}</span><IconButton aria-label={'Detalhes de '+s.name} onClick={()=>setExpanded(expanded===s.id?'':s.id)}><ChevronDown size={16}/></IconButton></div>{expanded===s.id&&<div className="source-details"><p>{s.affiliation}</p><p><strong>Último teste:</strong> {displayDate(s.checked_at)} · {s.detail?.message||'O canal está cadastrado, mas ainda não foi testado nesta instalação.'}</p><p><strong>Leitura:</strong> {s.connector==='feed'?'RSS / Atom':'Descoberta limitada de links na página'} · idioma {s.language}</p><p><strong>Temas:</strong> {(s.topics||[]).map((t:string)=>topics[t]).join(" · ")||"Cobertura geral"}</p><p>{s.selection_note}</p><p>{s.coverage_note}</p><a href={s.home} target="_blank" rel="noreferrer">Conhecer a fonte <ExternalLink size={12}/></a><a href={s.channel} target="_blank" rel="noreferrer">Abrir canal cadastrado <ExternalLink size={12}/></a></div>}</div>)}</div><div className="catalog-footer"><label className="form-field">Artigos lidos por fonte em cada coleta<input type="number" min="1" max="10" value={form.articles_per_source} onChange={e=>setForm({...form,articles_per_source:Number(e.target.value)})}/></label><p className="muted">A palavra-chave ou o tema seleciona as fontes especializadas. Expressões desconhecidas passam por uma classificação curta no Ollama local. Se houver dúvida, escolha um tema; sem palavra e sem tema, são usados os dez veículos gerais. Além dos itens de feed, até este número de páginas será lido por fonte. Não cobre toda a publicação nem o arquivo histórico.</p><button className="button primary" onClick={()=>action('Salvando seleção de fontes',save)}>Salvar seleção de fontes</button></div></section></section>
}

const root=document.getElementById('root');
if(root)createRoot(root).render(<React.StrictMode><App/></React.StrictMode>);
export {App,HistoryPage};
